import fs from 'node:fs';
const {input} = JSON.parse(fs.readFileSync(0, 'utf8'));
const values = input.values;
if (!Array.isArray(values) || values.length < 1 || values.length > 100 || !values.every(v => typeof v === 'number' && Number.isFinite(v))) throw new Error('values must contain 1 to 100 finite numbers');
const min = Math.min(...values), max = Math.max(...values);
const range = max - min;
if (!Number.isFinite(range)) throw new Error('range must be finite');
process.stdout.write(JSON.stringify({count: values.length, min, max, range}));

baseline.script:
import fs from 'node:fs';
const {input} = JSON.parse(fs.readFileSync(0, 'utf8'));
const values = input.values;
const min = values[0], max = values[values.length - 1];
process.stdout.write(JSON.stringify({count: values.length, min, max, range: max - min}));
